package org.dextur.reputation.storage;
import java.time.*;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;
import org.dextur.reputation.domain.policy.*;
import org.dextur.reputation.domain.policy.AdministrationData.*;
import org.dextur.reputation.domain.recovery.*;
import static org.dextur.reputation.storage.RecoveryFixtures.*;
import static org.junit.jupiter.api.Assertions.*;

final class PolicyContract {
    enum Scenario { SEMANTICS,LOCKS,RECOVERY_AFTER_ADMIN,PRECISION,IDEMPOTENCY_BOUNDS,CONCURRENT_ADDS,CONCURRENT_SET_VOTE,CONCURRENT_SET_RECOVERY,CONCURRENT_LOCK_VOTE,PENDING_REVIEW,OVERRIDES,QUEUED_TIMESTAMP }
    static AdministrationData.Request admin(UUID player,Type type,long value,Instant at){return new AdministrationData.Request(UUID.randomUUID(),player,"global",type,value,"",AdministrationData.Override.DEFAULT,"CONSOLE","test reason",at);}
    static AdministrationData.Request override(UUID player,String policy,AdministrationData.Override value,Instant at){return new AdministrationData.Request(UUID.randomUUID(),player,"global",Type.OVERRIDE,0,policy,value,"CONSOLE","test reason",at);}
    static void configured(StorageBackend b,Path dir)throws Exception{b.features(PolicyConfiguration.load(dir));}
    static void run(Scenario scenario,StorageBackend b,Path dir)throws Exception{
        if(scenario==Scenario.SEMANTICS||scenario==Scenario.PENDING_REVIEW)complete(b,dir);else seed(b,dir,rules(RecoveryRules.Type.ACTIVE_PLAYTIME));configured(b,dir);Instant at=NOW.plusSeconds(100);
        switch(scenario){
            case SEMANTICS->{var original=b.snapshot();long[] wanted={100,-100,0,25,-25,-50};Type[] types={Type.SET,Type.SET,Type.SET,Type.ADD,Type.ADD,Type.REMOVE};long[] values={100,-100,0,25,-50,25};for(int i=0;i<types.length;i++){var result=b.administer(admin(PLAYER,types[i],values[i],at.plusSeconds(i)));assertEquals(wanted[i],result.profile().visibleScore());assertEquals(result.profile(),b.getOrCreate(PLAYER,"global"));}var after=b.snapshot();assertEquals(original.votes(),after.votes());assertEquals(original.protection(),after.protection());assertEquals(original.recovery(),after.recovery());assertEquals(original.preferences(),after.preferences());assertEquals(6,after.administration().get(PLAYER,"global").audit().size());assertEquals(12,after.recovery().get(PLAYER,"global").lifetimeReward());assertEquals(-50,after.administration().get(PLAYER,"global").audit().getLast().resultingVisible());}
            case LOCKS->{var target=UUID.randomUUID();var lock=admin(PLAYER,Type.LOCK,0,at);b.administer(lock);var before=b.snapshot();assertTrue(b.administer(lock).duplicate());assertEquals(before,b.snapshot());for(var type:VoteType.values())assertThrows(PolicyDeniedException.class,()->b.vote("global",ProtectionFixtures.vote(PLAYER,target,type,"blocked"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at));assertEquals(before,b.snapshot());b.administer(admin(PLAYER,Type.UNLOCK,0,at));var request=ProtectionFixtures.vote(PLAYER,target,VoteType.POSITIVE,"allowed");b.vote("global",request,ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at);b.administer(admin(PLAYER,Type.LOCK,0,at));assertTrue(b.vote("global",request,ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at).duplicate());b.administer(admin(PLAYER,Type.UNLOCK,0,at));assertEquals(VoteRejectedException.Code.SELF,assertThrows(VoteRejectedException.class,()->b.vote("global",ProtectionFixtures.vote(PLAYER,PLAYER,VoteType.POSITIVE,"self"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at)).code());assertEquals(1,b.snapshot().votes().size());}
            case RECOVERY_AFTER_ADMIN->{b.administer(admin(PLAYER,Type.ADD,-20,NOW));b.recover(request(RecoveryData.Command.START,NOW));b.recover(sample(NOW,0,0));var change=b.recover(sample(NOW.plusSeconds(10),10,10));assertEquals(-15,change.profile().systemScore());assertEquals(-116,change.profile().visibleScore());var reward=change.state().rewards().getFirst();assertEquals(0,reward.systemBefore());assertEquals(5,reward.systemAfter());assertEquals(-20,b.snapshot().administration().contribution(PLAYER,"global"));}
            case PRECISION->{b.protection(ProtectionFixtures.rules(dir,false));var first=UUID.randomUUID();b.vote("global",ProtectionFixtures.vote(first,PLAYER,VoteType.POSITIVE,"fraction"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at);long precise=b.snapshot().protection().scores().stream().filter(s->s.player().equals(PLAYER)).findFirst().orElseThrow().currentUnits();assertEquals(-100650000,precise);assertEquals(100,b.administer(admin(PLAYER,Type.SET,100,at)).profile().visibleScore());assertEquals(precise,b.snapshot().protection().scores().stream().filter(s->s.player().equals(PLAYER)).findFirst().orElseThrow().currentUnits());b.vote("global",ProtectionFixtures.vote(UUID.randomUUID(),PLAYER,VoteType.POSITIVE,"second fraction"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at);assertEquals(101,b.getOrCreate(PLAYER,"global").visibleScore());assertEquals(-100,b.getOrCreate(PLAYER,"global").communityScore());assertEquals(2,b.snapshot().votes().size());}
            case IDEMPOTENCY_BOUNDS->{var op=admin(PLAYER,Type.SET,100,at);b.administer(op);var before=b.snapshot();assertTrue(b.administer(new AdministrationData.Request(op.operation(),PLAYER,"global",op.type(),op.requested(),"",AdministrationData.Override.DEFAULT,"CONSOLE","test reason",at.plusSeconds(1))).duplicate());assertEquals(before,b.snapshot());assertThrows(IllegalArgumentException.class,()->b.administer(new AdministrationData.Request(op.operation(),PLAYER,"global",Type.ADD,100,"",AdministrationData.Override.DEFAULT,"CONSOLE","test reason",at)));for(long n:new long[]{Long.MAX_VALUE,Long.MIN_VALUE,10001})assertThrows(Exception.class,()->b.administer(admin(PLAYER,Type.ADD,n,at)));assertThrows(Exception.class,()->b.administer(admin(PLAYER,Type.REMOVE,-25,at)));var noReason=new AdministrationData.Request(UUID.randomUUID(),PLAYER,"global",Type.ADD,1,"",AdministrationData.Override.DEFAULT,"CONSOLE","",at);assertThrows(Exception.class,()->b.administer(noReason));assertEquals(before,b.snapshot());UUID operator=UUID.randomUUID();var actor=new AdministrationData.Request(UUID.randomUUID(),PLAYER,"global",Type.ADD,1,"",AdministrationData.Override.DEFAULT,operator.toString(),"operator reason",at);assertEquals(operator.toString(),b.administer(actor).audit().request().actor());}
            case CONCURRENT_ADDS->{try(var executor=Executors.newFixedThreadPool(8)){var futures=new ArrayList<Future<?>>();for(int i=0;i<24;i++)futures.add(executor.submit(()->{try{b.administer(admin(PLAYER,Type.ADD,1,at));}catch(Exception e){throw new CompletionException(e);}}));for(var f:futures)f.get();}assertEquals(-77,b.getOrCreate(PLAYER,"global").visibleScore());assertEquals(24,b.snapshot().administration().get(PLAYER,"global").audit().size());}
            case CONCURRENT_SET_VOTE->{race(()->b.administer(admin(PLAYER,Type.SET,100,at)),()->b.vote("global",ProtectionFixtures.vote(UUID.randomUUID(),PLAYER,VoteType.POSITIVE,"concurrent"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at));assertTrue(Set.of(100L,101L).contains(b.getOrCreate(PLAYER,"global").visibleScore()));assertEquals(1,b.snapshot().votes().size());assertEquals(100,b.snapshot().administration().get(PLAYER,"global").audit().getFirst().resultingVisible());}
            case CONCURRENT_SET_RECOVERY->{b.recover(request(RecoveryData.Command.START,NOW));b.recover(sample(NOW,0,0));race(()->b.administer(admin(PLAYER,Type.SET,100,NOW.plusSeconds(10))),()->b.recover(sample(NOW.plusSeconds(10),10,10)));assertTrue(Set.of(100L,105L).contains(b.getOrCreate(PLAYER,"global").visibleScore()));assertEquals(5,b.snapshot().recovery().get(PLAYER,"global").lifetimeReward());assertEquals(1,b.snapshot().recovery().get(PLAYER,"global").rewards().size());}
            case CONCURRENT_LOCK_VOTE->{UUID target=UUID.randomUUID();race(()->b.administer(admin(PLAYER,Type.LOCK,0,at)),()->{try{return b.vote("global",ProtectionFixtures.vote(PLAYER,target,VoteType.POSITIVE,"race"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at);}catch(PolicyDeniedException denied){return null;}});assertTrue(b.snapshot().administration().get(PLAYER,"global").votingLocked());assertTrue(b.snapshot().votes().size()<=1);assertThrows(PolicyDeniedException.class,()->b.vote("global",ProtectionFixtures.vote(PLAYER,UUID.randomUUID(),VoteType.NEGATIVE,"after"),ProtectionFixtures.mature(),ProtectionFixtures.eligibility(),at));}
            case PENDING_REVIEW->{var pending=b.snapshot().protection().assessments().stream().filter(a->a.status()==org.dextur.reputation.domain.protection.ProtectionData.Status.PENDING).findFirst().orElseThrow();var before=b.snapshot();race(()->b.administer(admin(pending.target(),Type.SET,100,at)),()->b.review(UUID.randomUUID(),pending.voteId(),UUID.randomUUID(),"approved",org.dextur.reputation.domain.protection.ProtectionData.Review.ACCEPT,pending.revision(),at));assertEquals(before.votes(),b.snapshot().votes());assertEquals(before.recovery(),b.snapshot().recovery());assertTrue(Set.of(99L,100L).contains(b.getOrCreate(pending.target(),"global").visibleScore()));assertEquals(org.dextur.reputation.domain.protection.ProtectionData.Status.ACCEPTED,b.inspectVote(pending.voteId()).status());}
            case QUEUED_TIMESTAMP->{b.administer(admin(PLAYER,Type.ADD,1,at));var next=b.administer(admin(PLAYER,Type.ADD,1,at.minusSeconds(1)));assertEquals(-99,next.profile().visibleScore());assertEquals(at,next.audit().request().at());assertEquals(at,next.profile().updatedAt());}
            case OVERRIDES->{b.administer(override(PLAYER,"chat.send",AdministrationData.Override.FORCE_DENY,at));var input=b.policyInput(PLAYER,"global");assertEquals(ReputationPolicyResult.Decision.DENY,PolicyEngine.evaluate(input,PolicyConfiguration.load(dir),"chat.send",Map.of(),at,false).decision());b.administer(override(PLAYER,"chat.send",AdministrationData.Override.DEFAULT,at));assertEquals(ReputationPolicyResult.Decision.ALLOW,PolicyEngine.evaluate(b.policyInput(PLAYER,"global"),PolicyConfiguration.load(dir),"chat.send",Map.of(),at,false).decision());b.administer(override(PLAYER,"reputation.vote",AdministrationData.Override.FORCE_ALLOW,at));b.administer(admin(PLAYER,Type.LOCK,0,at));assertEquals(ReputationPolicyResult.Decision.DENY,PolicyEngine.evaluate(b.policyInput(PLAYER,"global"),PolicyConfiguration.load(dir),"reputation.vote",Map.of(),at,true).decision());var before=b.snapshot();assertThrows(Exception.class,()->b.administer(override(PLAYER,"support.emergency-contact",AdministrationData.Override.FORCE_DENY,at)));assertEquals(before,b.snapshot());}
        }
        var encoded=new SnapshotCodec().encode(5,b.snapshot());assertEquals(b.snapshot(),new SnapshotCodec().decode(encoded).snapshot());
    }
    @FunctionalInterface interface Work {Object run()throws Exception;}
    static void race(Work first,Work second)throws Exception{var gate=new CyclicBarrier(2);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{gate.await();return first.run();});var b=pool.submit(()->{gate.await();return second.run();});a.get(20,TimeUnit.SECONDS);b.get(20,TimeUnit.SECONDS);}}
}
